head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70009";
scwin.lbl_attach_span = null;
scwin.lbl_attach_span_two = null;
scwin.lbl_caut_span = null;
scwin.lbl_caut_span_two = null;
scwin.cominfo = null;
scwin.attach = null;
scwin.caut = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — integUsrId, odsDisclsProcsStatCd, mainnumber, tempSaveYn
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrId, session.user.kclicUsrTpId

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_tempdisclsDocTxtfile", attr: "label", fn: function () { return String(dma_disclosureVo.get("disclsDocTxtfile")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"mainnumber":"0"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_doc_Submit", fn: function(){ return ($c.session.getUserInfo("usrId")  !== (dma_pageContext.get("integUsrId") ?? "")); } }, { id: "btn_documentSubmit", fn: function(){ return ($c.session.getUserInfo("kclicUsrTpId")  === 'LIST_CORP_DISCLS' && ((dma_pageContext.get("odsDisclsProcsStatCd") ?? "") === '00' || (dma_pageContext.get("odsDisclsProcsStatCd") ?? "") === '30')); } }, { id: "btn_goWrite", fn: function(){ return ($c.session.getUserInfo("kclicUsrTpId")  === 'LIST_CORP_DISCLS' && ((dma_pageContext.get("odsDisclsProcsStatCd") ?? "") === '00' || (dma_pageContext.get("odsDisclsProcsStatCd") ?? "") === '30')); } }, { id: "btn_doc_Submit", fn: function(){ return ($c.session.getUserInfo("kclicUsrTpId")  === 'LIST_CORP_DISCLS' && ((dma_pageContext.get("odsDisclsProcsStatCd") ?? "") === '00' || (dma_pageContext.get("odsDisclsProcsStatCd") ?? "") === '30')); } }, { id: "if_wrtrptMaindocTpCd", fn: function(){ return ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "if_mainnumber", fn: function(){ return ((dma_pageContext.get("mainnumber") ?? "") === 0); } }, { id: "if_wrtrptMaindocTpCd_2", fn: function(){ return ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()) === '2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_67", entity: "dlt_disclosureContentVoArr", countIds: [], cells: [{ childId: "__rc4", fn: function (v, i) { return String(v("documentHtml")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return dlt_disclosureContentVoArr.getCellData(0, "formKorNm"); } },
        { childId: "__rb5", fn: function () { return String(String(String((dma_pageContext.get("cautnContent") ?? "")) == null ? '' : String((dma_pageContext.get("cautnContent") ?? ""))).split(String.fromCharCode(10)).join('<br/>')); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.lbl_caut_span.setStyle("display", "");
        scwin.lbl_caut_span_two.setStyle("display", "none");
        scwin.caut.setStyle("display", "none");
        scwin.lbl_attach_span.setStyle("display", "");
        scwin.lbl_attach_span_two.setStyle("display", "none");
        scwin.attach.setStyle("display", "none");
        $("#txt_lblCominfo").click(function() {
                if (!$(this).hasClass('on')) {
                    $c.util.getComponent("cominfo").setStyle("display", "block");
                    scwin.cominfo.setStyle("display", "");
                    (($c.util.getComponent('txt_lblCominfo')) && ($c.util.getComponent('txt_lblCominfo')).addClass ? ($c.util.getComponent('txt_lblCominfo')).addClass('on') : console.error('[sdd] addClass 미지원 컴포넌트: txt_lblCominfo'));
                } else {
                    scwin.cominfo.setStyle("display", "none");
                    (($c.util.getComponent('txt_lblCominfo')) && ($c.util.getComponent('txt_lblCominfo')).removeClass ? ($c.util.getComponent('txt_lblCominfo')).removeClass('on') : console.error('[sdd] removeClass 미지원 컴포넌트: txt_lblCominfo'));
                }
        });
        $("#txt_lblAttach").click(function() {
                scwin.lbl_attach_span.setStyle("display", "none");
                scwin.lbl_attach_span_two.setStyle("display", "");
                scwin.attach.setStyle("display", "");
        });
        $("#txt_lblAttachTwo").click(function() {
                scwin.lbl_attach_span.setStyle("display", "");
                scwin.lbl_attach_span_two.setStyle("display", "none");
                scwin.attach.setStyle("display", "none");
        });
        $("#txt_lblCaut").click(function() {
                scwin.lbl_caut_span.setStyle("display", "none");
                scwin.lbl_caut_span_two.setStyle("display", "");
                scwin.caut.setStyle("display", "");
        });
        $("#txt_lblCautTwo").click(function() {
                scwin.lbl_caut_span.setStyle("display", "");
                scwin.lbl_caut_span_two.setStyle("display", "none");
                scwin.caut.setStyle("display", "none");
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70009.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fnDocumentSubmit();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.lbl_attach_span = $c.util.getComponent('lbl_attach_span');
        scwin.lbl_attach_span_two = $c.util.getComponent('lbl_attach_span_two');
        scwin.lbl_caut_span = $c.util.getComponent('lbl_caut_span');
        scwin.lbl_caut_span_two = $c.util.getComponent('lbl_caut_span_two');
        scwin.cominfo = $c.util.getComponent('cominfo');
        scwin.attach = $c.util.getComponent('attach');
        scwin.caut = $c.util.getComponent('caut');
        scwin.init_ctxDefaults();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70009.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
