    try {
        scwin.docSubmit('Y',10,'' + dma_disclosureVo.get("applNo") + '',(String(((dma_pageContext.get("integUsrId") ?? "")) == null ? '' : ((dma_pageContext.get("integUsrId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("integUsrId") ?? "")) == null ? '' : ((dma_pageContext.get("integUsrId") ?? "")))))

