///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_excel
 * @description excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_excel = async function () {
    try { return await $c.data.downFile("/discls/disclosure.do?method=searchDocumentPrintExcel", "", ($c.util.getComponent("dma_excelReq") ? $c.util.getComponent("dma_excelReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/discls/disclosure.do?method=disclosureCreate",
        ref: "dma_goWriteReq",
        target: "dlt_disclosureContentVoArr=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goPrint
 * @description go Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPrint = async function () {
    try { return await $c.data.downFile("/discls/disclosure.do?method=searchDocumentPrint", "", ($c.util.getComponent("dma_goPrintReq") ? $c.util.getComponent("dma_goPrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fnDocumentSubmit
 * @description fn Document Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDocumentSubmit = async function () {
    const sbmOptions = {
        id: "tx_fnDocumentSubmit",
        method: "post",
        action: "/discls/disclosure.do?method=formatSendInfo",
        ref: "dma_fnDocumentSubmitReq",
        target: "dlt_disclosureContentVoArr=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

