/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    let documentHtml = '';
    if ($c.util.getComponent("cominfo")) {
        if ($c.util.getComponent("cominfo").getStyle("display") === 'block') {
            documentHtml = documentHtml + $c.util.getComponent("cominfo").innerHTML;
        }
    }
    if ($c.util.getComponent("maindoc")) {
        if ($c.util.getComponent("maindoc").getStyle("display") === 'block') {
            documentHtml = documentHtml + $c.util.getComponent("maindoc").innerHTML;
        }
    }
    if ($c.util.getComponent("attach")) {
        if ($c.util.getComponent("attach").getStyle("display") === 'block') {
            documentHtml = documentHtml + $c.util.getComponent("attach").innerHTML;
        }
    }
    if ($c.util.getComponent("caut")) {
        if ($c.util.getComponent("caut").getStyle("display") === 'block') {
            documentHtml = documentHtml + $c.util.getComponent("caut").innerHTML;
        }
    }
    $c.util.getComponent('dma_excelReq').set('documentHtml', documentHtml);
    (document.submitFrm || { elements: [] }).action = 'disclosure.do?method=searchDocumentPrintExcel';
    await scwin.tx_fn_excel();
};

/**
