 * @param {String} exmptObjDisclsYn exmptObjDisclsYn
 * @param {String} disclsObjIsuCd disclsObjIsuCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (applNo, disclsMaindocFormCd, disclsMaindocFormVer, currFormVer, currEngFormVer, beforeFormVer, beforeEngFormVer, oldFormVerUseYn, docNo, formCd, formVer, langTpCd, tgtIsurCd, tgtFssUnqNo, disclsAcptTpCd, wrtrptMaindocTpCd, disclsObjCorpIsurNm, subcomDisclsYn, formUpclssCd, tgtComEngNm, disclsObjRepIsuSrtCd, exmptObjDisclsYn, disclsObjIsuCd) {
    (document.writeForm || { elements: [] }).action = '/discls/disclosure.do?method=disclosureCreate';
    $c.util.getComponent('dma_excelReq').set('applNo', applNo);
    if (docNo !== '00000000000000') {
        $c.util.getComponent('dma_excelReq').set('docNo', docNo);
    }
    $c.util.getComponent('dma_excelReq').set('disclsMaindocFormVer', disclsMaindocFormVer);
    $c.util.getComponent('dma_excelReq').set('formVer', formVer);
    $c.util.getComponent('dma_excelReq').set('disclsMaindocFormCd', disclsMaindocFormCd);
    $c.util.getComponent('dma_excelReq').set('formCd', formCd);
    $c.util.getComponent('dma_excelReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_excelReq').set('tgtIsurCd', tgtIsurCd);
    $c.util.getComponent('dma_excelReq').set('tgtIsuCd', disclsObjIsuCd);
    $c.util.getComponent('dma_excelReq').set('tgtFssUnqNo', tgtFssUnqNo);
    $c.util.getComponent('dma_excelReq').set('tgtComNm', disclsObjCorpIsurNm);
    $c.util.getComponent('dma_excelReq').set('tgtIsuSrtCd', disclsObjRepIsuSrtCd);
    $c.util.getComponent('dma_excelReq').set('tgtComEngNm', tgtComEngNm);
    $c.util.getComponent('dma_excelReq').set('disclsAcptTpCd', disclsAcptTpCd);
    $c.util.getComponent('dma_excelReq').set('wrtrptMaindocTpCd', wrtrptMaindocTpCd);
    $c.util.getComponent('dma_excelReq').set('subcomDisclsYn', subcomDisclsYn);
    $c.util.getComponent('dma_excelReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_excelReq').set('exmptObjDisclsYn', exmptObjDisclsYn);
    $c.util.getComponent('dma_excelReq').set('reviewYn', "Y");
    (document.writeForm || { elements: [] }).target = 'listPage';
    await scwin.tx_fn_goWrite();
    $c.win.closePopup();
};

/**
 * @method
 * @name goPrint
