/**
 * @method
 * @name documentSubmit
 * @description document Submit 처리
 * @param {*} isSecureDocumnet isSecureDocumnet
 * @param {String} odsDisclsProcsStatCd odsDisclsProcsStatCd
 * @param {*} applNo applNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentSubmit = async function (isSecureDocumnet, odsDisclsProcsStatCd, applNo) {
    if ('1' !== (String(((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })())) == null ? '' : ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })())) == null ? '' : ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()))))) {
        await $c.win.alert("본문 공시가 [작성]된 상태일때 전송이 가능합니다.");
        return;
    }
    confirmF("KIND 제출시스템으로 전송하시겠습니까?", async function() {
            await scwin.documentSubmitDo(isSecureDocumnet, odsDisclsProcsStatCd, applNo);
    });
};

