    });
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name documentSubmitDoDone
 * @description document Submit Do Done 처리
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentSubmitDoDone = async function (data) {
    if (data.returnValue === 'Y') {
        await alertE("KIND 제출시스템으로 전송되었습니다.", function() {
                (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { /* TODO Stage2: [sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다) */ } })();
                $c.win.closePopup();
        });
    }
};

/**
 * @method
 * @name documentSubmitDo
 * @description document Submit Do 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentSubmitDo = async function () {
    const r = await scwin.tx_fn_document_submit_do();
    try {
        scwin.documentSubmitDoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldods70009.fn_document_submit_do' });
    }
    return r;
};

